records.source:
procedure main()
local x
local y
local total
x := 0
y := 0
total := 0
while x < 4 do {
  y := 0
  while y < 3 do {
    if x > y then {
      total := total + 1
    } else {
      total := total - 1
    }
    y := y + 1
  }
  x := x + 1
}
write(total)
end

